import { useEffect, useMemo, useRef, useState } from 'react';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  DEFAULT_SORT,
  EYEBROW,
  SEARCH_PLACEHOLDER,
  SUBTITLE,
  TITLE,
  fetchSentOffers,
  filterSentOffers,
  resultCountLabel,
  sortSentOffers,
  type SentOffer,
  type SortColumn,
  type SortDirection,
} from '../../lib/sent-offers';
import { SentOffersTable } from './SentOffersTable';
import styles from './SentOffers.module.css';

interface SentOffersProps {
  profile: MemberProfile;
  onOpenThread?: (threadId: string) => void;
}

/**
 * VND-01 · Mis Ofertas — vista del vendedor.
 *
 * La pantalla posee TODO el estado: ofertas, carga, error, texto de búsqueda
 * y ordenación. La tabla recibe únicamente las filas ya filtradas y ya
 * ordenadas; el orden de las operaciones es FILTRAR y luego ORDENAR (§4 y §5.4).
 */
export function SentOffers({ profile, onOpenThread }: SentOffersProps) {
  const [offers, setOffers] = useState<SentOffer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);
  const [query, setQuery] = useState('');
  const [sort, setSort] = useState<{ column: SortColumn; direction: SortDirection }>(DEFAULT_SORT);

  const fetchedRef = useRef(false);

  useEffect(() => {
    // Una sola llamada al montar, aunque React remonte el efecto en StrictMode.
    if (fetchedRef.current) return;
    fetchedRef.current = true;

    let cancelled = false;
    fetchSentOffers(profile.orgId)
      .then((data) => {
        if (!cancelled) {
          setOffers(data);
          setLoading(false);
        }
      })
      .catch((err) => {
        if (!cancelled) {
          setError(err);
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId]);

  const visibleOffers = useMemo(() => {
    const filtered = filterSentOffers(offers, query);
    return sortSentOffers(filtered, sort.column, sort.direction);
  }, [offers, query, sort]);

  const hasQuery = query.trim().length > 0;

  const handleSort = (column: SortColumn) => {
    setSort((prev) =>
      prev.column === column
        ? { column, direction: prev.direction === 'asc' ? 'desc' : 'asc' }
        : { column, direction: 'asc' },
    );
  };

  const handleOpenThread = (threadId: string) => {
    onOpenThread?.(threadId);
  };

  return (
    <section className={styles.body} data-testid="selling-body" aria-busy={loading ? 'true' : 'false'}>
      <div className={styles.eyebrow}>{EYEBROW}</div>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.subtitle}>{SUBTITLE}</p>

      {error ? (
        <div role="alert" className={styles.error}>
          {errorMessage(error)}
        </div>
      ) : (
        <>
          <div className={styles.searchBar}>
            <div className={styles.searchWrap}>
              <input
                type="text"
                className={styles.searchInput}
                placeholder={SEARCH_PLACEHOLDER}
                value={query}
                onChange={(event) => setQuery(event.target.value)}
              />
              {query.length > 0 && (
                <button
                  type="button"
                  className={styles.clearButton}
                  onClick={() => setQuery('')}
                  aria-label="Limpiar búsqueda"
                >
                  ×
                </button>
              )}
            </div>
            <span className={styles.resultCount}>{resultCountLabel(visibleOffers.length)}</span>
          </div>

          <SentOffersTable
            offers={visibleOffers}
            sort={sort}
            onSort={handleSort}
            onOpenThread={handleOpenThread}
            hasQuery={hasQuery}
          />
        </>
      )}
    </section>
  );
}

.tableOuter {
  /* El mock pinta la tabla sobre blanco puro (#FFFFFF), que no es un token de
     la paleta; --bw-warm-cream (#FAF8F4) es la superficie más clara definida
     y cumple el mismo papel sin inventar un valor nuevo. */
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: auto;
  max-height: calc(100vh - 270px);
}

.table {
  width: 100%;
  border-collapse: collapse;
}

.th {
  padding: 9px 14px;
  text-align: left;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--bw-steel-mist);
  background: var(--bw-surface-mist);
  border-bottom: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  position: sticky;
  top: 0;
  z-index: 1;
  user-select: none;
}

.thSortable {
  padding: 0;
}

.sortButton {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  padding: 9px 14px;
  background: none;
  border: none;
  font: inherit;
  color: inherit;
  text-transform: inherit;
  letter-spacing: inherit;
  cursor: pointer;
  white-space: nowrap;
}

.sortButton:hover {
  color: var(--bw-deep-steel);
}

.sortIndicator {
  font-style: normal;
  font-size: var(--bw-size-hint);
  opacity: 0.35;
  color: var(--bw-steel-mist);
}

.sortActive .sortIndicator {
  opacity: 1;
  color: var(--bw-calibration-blue);
}

.td {
  padding: 10px 14px;
  font-size: var(--bw-size-input);
  color: var(--bw-ink-steel);
  border-bottom: 1px solid var(--bw-divider-mist);
  vertical-align: middle;
  white-space: nowrap;
}

.table tbody tr:last-child td {
  border-bottom: none;
}

.table tbody tr:hover td {
  background: var(--bw-row-hover-tint);
}

.reference {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.partNumber {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-input);
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.brand {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
}

.date {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-label);
  color: var(--bw-input-placeholder);
}

.stateBadge {
  display: inline-block;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  letter-spacing: 0.04em;
  padding: 2px 7px;
  border-radius: 2px;
  border: 1px solid transparent;
  white-space: nowrap;
}

.statePendiente {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border-color: var(--bw-badge-warning-border);
}

.stateAceptada {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border-color: var(--bw-badge-success-border);
}

.stateRechazada {
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  border-color: var(--bw-badge-danger-border);
}

/* Cuarto estado del CHECK de 0003, que la spec §5.2 no lista. El mock usaba
   el gris para EXPIRADA; 'Superada por contraoferta' es un estado terminal
   neutro, así que usa la familia de badge neutro. */
.stateSuperada {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border-color: var(--bw-badge-neutral-border);
}

.actionButton {
  height: 26px;
  padding: 0 10px;
  border-radius: 4px;
  font-size: var(--bw-size-label);
  font-weight: 500;
  cursor: pointer;
  font-family: var(--bw-font-body);
  white-space: nowrap;
  transition: all 0.12s;
}

.actionPrimary {
  /* El texto del botón primario es blanco en el mock; al no existir token
     blanco puro, se usa la superficie más clara de la paleta. */
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  border: none;
}

.actionPrimary:hover {
  opacity: 0.87;
}

.actionGhost {
  background: transparent;
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel-strong);
}

.actionGhost:hover {
  border-color: var(--bw-input-placeholder);
  color: var(--bw-ink-steel);
}

.emptyCell {
  padding: 48px 20px;
  text-align: center;
  color: var(--bw-input-placeholder);
  font-size: var(--bw-size-body);
  white-space: normal;
}

import {
  EMPTY_NO_MATCHES,
  EMPTY_NO_OFFERS,
  rowActionLabel,
  sentAtLabel,
  type SentOffer,
  type SortColumn,
  type SortDirection,
} from '../../lib/sent-offers';
import styles from './SentOffersTable.module.css';

interface Column {
  key: SortColumn | null;
  label: string;
}

const COLUMNS: Column[] = [
  { key: 'referencia', label: 'Referencia' },
  { key: 'organizacion', label: 'Organización' },
  { key: 'estado', label: 'Estado' },
  { key: 'fecha', label: 'Fecha' },
  { key: null, label: 'Acciones' },
];

/**
 * Los cuatro estados del CHECK `thread_items_estado_oferta_chk` (0003). La
 * spec §5.2 los escribe en mayúsculas y lista `EXPIRADA`; manda el esquema y
 * la capability `offer-card`: los literales van capitalizados y tal cual,
 * sin `text-transform` ni traducción. El cuarto estado —que la §5.2 no
 * contempla— se pinta con el badge neutro.
 */
const STATE_CLASS: Record<SentOffer['state'], string> = {
  Pendiente: styles.statePendiente,
  Aceptada: styles.stateAceptada,
  Rechazada: styles.stateRechazada,
  'Superada por contraoferta': styles.stateSuperada,
};

interface SentOffersTableProps {
  offers: SentOffer[];
  sort: { column: SortColumn; direction: SortDirection };
  onSort: (column: SortColumn) => void;
  onOpenThread: (threadId: string) => void;
  hasQuery: boolean;
}

/**
 * Tabla de VND-01 · Mis Ofertas.
 *
 * Presentacional y sin estado propio: recibe las filas ya filtradas y ya
 * ordenadas y no las vuelve a tocar. Los dos estados vacíos viven aquí — "no
 * hay filas" es un estado de la lista, no de la pantalla (misma lección que
 * MSG-01 y SRCH-01).
 */
export function SentOffersTable({ offers, sort, onSort, onOpenThread, hasQuery }: SentOffersTableProps) {
  return (
    <div className={styles.tableOuter}>
      <table className={styles.table}>
        <thead>
          <tr>
            {COLUMNS.map((col) => {
              if (col.key === null) {
                return (
                  <th key={col.label} scope="col" className={styles.th}>
                    {col.label}
                  </th>
                );
              }

              const active = sort.column === col.key;
              return (
                <th
                  key={col.label}
                  scope="col"
                  aria-sort={active ? (sort.direction === 'asc' ? 'ascending' : 'descending') : 'none'}
                  className={`${styles.th} ${styles.thSortable}`}
                >
                  <button
                    type="button"
                    className={active ? `${styles.sortButton} ${styles.sortActive}` : styles.sortButton}
                    onClick={() => onSort(col.key)}
                  >
                    {col.label}
                    <span className={styles.sortIndicator} aria-hidden="true">
                      {active ? (sort.direction === 'asc' ? '↑' : '↓') : '↕'}
                    </span>
                  </button>
                </th>
              );
            })}
          </tr>
        </thead>
        {offers.length === 0 ? (
          <tbody>
            <tr>
              <td colSpan={5} className={`${styles.td} ${styles.emptyCell}`}>
                {hasQuery ? EMPTY_NO_MATCHES : EMPTY_NO_OFFERS}
              </td>
            </tr>
          </tbody>
        ) : (
          <tbody>
            {offers.map((offer) => (
              <tr key={offer.id} data-testid="sent-offer-row" data-offer-id={offer.id}>
                <td className={styles.td}>
                  <div className={styles.reference}>
                    <span className={styles.partNumber}>{offer.partNumber ?? '—'}</span>
                    {offer.brand ? <span className={styles.brand}>{offer.brand}</span> : null}
                  </div>
                </td>
                <td className={styles.td}>{offer.counterpartyName}</td>
                <td className={styles.td}>
                  <span className={`${styles.stateBadge} ${STATE_CLASS[offer.state]}`}>{offer.state}</span>
                </td>
                <td className={styles.td}>
                  <span className={styles.date}>{sentAtLabel(offer.createdAt)}</span>
                </td>
                <td className={styles.td}>
                  <button
                    type="button"
                    className={
                      offer.state === 'Aceptada'
                        ? `${styles.actionButton} ${styles.actionPrimary}`
                        : `${styles.actionButton} ${styles.actionGhost}`
                    }
                    onClick={() => onOpenThread(offer.threadId)}
                  >
                    {rowActionLabel(offer.state)}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        )}
      </table>
    </div>
  );
}
